package hexadecimal

import (
	"errors"
)

// ErrSyntax is returned when the input is not a valid hexadecimal string.
var ErrSyntax = errors.New("syntax error: invalid hexadecimal input")

// ErrRange is returned when the input overflows the range of int64.
var ErrRange = errors.New("range error: value out of range for int64")

// ParseHex converts a hexadecimal string (e.g. "10af8c") to its decimal
// equivalent using first principles, without any conversion libraries.
func ParseHex(in string) (int64, error) {
	if len(in) == 0 {
		return 0, ErrSyntax
	}

	var result int64
	for _, r := range in {
		var digit int64
		switch {
		case r >= '0' && r <= '9':
			digit = int64(r - '0')
		case r >= 'a' && r <= 'f':
			digit = int64(r-'a') + 10
		case r >= 'A' && r <= 'F':
			digit = int64(r-'A') + 10
		default:
			return 0, ErrSyntax
		}

		// Detect overflow before multiplying: result*16+digit must stay
		// within int64 range.
		if result > (maxInt64-digit)/16 {
			return 0, ErrRange
		}
		result = result*16 + digit
	}

	return result, nil
}

const maxInt64 = int64(1<<63 - 1)

// HandleErrors takes a list of inputs for ParseHex and returns a matching
// list of "none", "syntax", or "range" according to the error.
func HandleErrors(inputs []string) []string {
	results := make([]string, len(inputs))
	for i, in := range inputs {
		_, err := ParseHex(in)
		switch {
		case err == nil:
			results[i] = "none"
		case errors.Is(err, ErrRange):
			results[i] = "range"
		default:
			results[i] = "syntax"
		}
	}
	return results
}

